        "Valor": [
            roc_auc_score(y_bank_test, bank_test_proba),
            average_precision_score(y_bank_test, bank_test_proba),
            balanced_accuracy_score(y_bank_test, bank_pred_050),
            bank_best_threshold,
            bank_precision[bank_best_idx],
            bank_recall[bank_best_idx],
